SELECT cs. * FROM course_status cs
JOIN student_courses sc ON cs.students_courses_id = sc.id
WHERE sc.student_id = #{studentId}

SELECT * FROM course_status WHERE students_courses_id = #{courseId}
ORDER BY id DESC
LIMIT 1

